import java.util.Iterator;
import java.util.List;
import java.util.Random;


public abstract class Predator extends Animal {


	private static final Random rand = Randomizer.getRandom();

	private boolean cannibal;

	private int additionalFoodValue;


	public Predator(boolean randomAge, Field field, Location location) {
		super(field, location);
		if (randomAge) {
			setAge(rand.nextInt(getMaxAge()));
			setFoodLevel(rand.nextInt(5));
		} else {
			setAge(0);
			setFoodLevel(6);
		}
		cannibal = false;
		additionalFoodValue = 0;
		setMaxSickStep(30);
	}


	protected void normalAct(List<Animal> newAnimals) {
		giveBirth(newAnimals);

		Location newLocation = findFood();
		if (isAlive()) {
			if (newLocation == null) {

				newLocation = getField().freeAnimalAdjacentLocation(getLocation());
			}

			if (newLocation != null) {
				setLocation(newLocation);
			} else {

				setDead();
			}
		}
	}


	private Location findFood() {
		Field field = getField();
		List<Location> adjacent = field.adjacentAnimalLocations(getLocation());
		Iterator<Location> it = adjacent.iterator();
		while (it.hasNext()) {
			Location where = it.next();
			Object animal = field.getAnimalAt(where);
			if (animal instanceof Animal) {
				Animal nearAnimal = (Animal) animal;

				if (nearAnimal.getFoodChainLevel() < this.getFoodChainLevel()) {

					if (nearAnimal.isAlive()) {
						nearAnimal.setDead();
						setFoodLevel(nearAnimal.getFoodValue() + additionalFoodValue);
						return where;
					}
				}


				if (nearAnimal.getFoodChainLevel() == this.getFoodChainLevel()) {
					if (nearAnimal.isAlive() && this.isCannibal()) {
						if (getFoodLevel() < 2 && nearAnimal.getClass().equals(this.getClass())) {
							nearAnimal.setDead();
							setFoodLevel(nearAnimal.getFoodValue() + additionalFoodValue);
							return where;
						}
					}
				}
			}
		}
		return null;
	}


	public boolean isCannibal() {
		return cannibal;
	}


	public void toggleCannibal() {
		cannibal = !cannibal;
	}


	protected int getAdditionalFoodValue() {
		return additionalFoodValue;
	}


	protected void setAdditionalFoodValue(int inputValue) {
		additionalFoodValue = inputValue;
	}
}
import java.util.List;
import java.util.Random;


public abstract class Prey extends Animal {

	private static final Random rand = Randomizer.getRandom();


	public Prey(boolean randomAge, Field field, Location location) {
		super(field, location);
		setAge(0);
		setFoodLevel(6);
		if (randomAge) {
			setAge(rand.nextInt(getMaxAge()));
		}
		setMaxSickStep(20);
	}


	protected void normalAct(List<Animal> newAnimals) {
		findFood();
		giveBirth(newAnimals);

		Location newLocation = getField().freeAnimalAdjacentLocation(getLocation());
		if (newLocation != null) {
			setLocation(newLocation);
		} else {

			setDead();
		}
	}


	private void findFood() {
		Field field = getField();
		Location where = getLocation();
		Object plant = field.getPlantAt(where);

		if (plant instanceof Plant) {
			Plant nearPlant = (Plant) plant;

			if (nearPlant.canEat()) {
				nearPlant.reduceStage();
				setFoodLevel(8);
			}
		}
	}
}

import java.util.HashMap;


public class FieldStats {

	private HashMap<Class, Counter> counters;

	private boolean countsValid;


	public FieldStats() {


		counters = new HashMap<>();
		countsValid = true;
	}


	public String getPopulationDetails(Field field) {
		StringBuffer buffer = new StringBuffer();
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class key : counters.keySet()) {
			Counter info = counters.get(key);
			buffer.append(info.getName());
			buffer.append(": ");
			buffer.append(info.getCount());
			buffer.append(' ');
		}
		return buffer.toString();
	}


	public void reset() {
		countsValid = false;
		for (Class key : counters.keySet()) {
			Counter count = counters.get(key);
			count.reset();
		}
	}


	public void incrementCount(Class animalClass) {
		Counter count = counters.get(animalClass);
		if (count == null) {


			count = new Counter(animalClass.getName());
			counters.put(animalClass, count);
		}
		count.increment();
	}


	public void countFinished() {
		countsValid = true;
	}


	public boolean isViable(Field field) {

		int nonZero = 0;
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class key : counters.keySet()) {
			Counter info = counters.get(key);
			if (info.getCount() > 0) {
				nonZero++;
			}
		}
		return nonZero > 1;
	}


	private void generateCounts(Field field) {
		reset();
		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Object animal = field.getAnimalAt(row, col);
				if (animal != null) {
					incrementCount(animal.getClass());
				}
			}
		}
		countsValid = true;
	}


	public int getPopulationCount(Field field, Class key) {
		if (!countsValid) {
			generateCounts(field);
		}
		int total = 0;
		for (Class currentKey : counters.keySet()) {
			if (currentKey.equals(key)) {
				Counter counter = counters.get(currentKey);
				total = total + counter.getCount();
			}
		}
		return total;
	}
}

import javax.swing.*;
