124	
125		public void simulateOneStep() {
126			step++;
127			climate.updateClimate(step);
128	
129			updatePlants();
130			List<Animal> newAnimals = new ArrayList<>();
131	
132			for (Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
133				Animal animal = it.next();
134				animal.act(newAnimals, currentTimeCycle);
135				if (!animal.isAlive()) {
136					it.remove();
137				}
138			}
139	
140	
141			animals.addAll(newAnimals);
142	
143			if (step % TIMECYCLE_LENGTH == 0) {
144				currentTimeCycle = currentTimeCycle.toggle();
145			}
146	
147			sickPercentage = calculateSickPercentage();
148			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
149			graphView.showStatus(step, field);
150		}
