152	
153		public void reset() {
154			step = 0;
155			animals.clear();
156			plants.clear();
157			populate();
158			currentTimeCycle = TimeCycle.DAY;
159			climate.setCurrentWeather(Weather.SUN);
160	
161			sickPercentage = 0;
162			graphView.reset();
163			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
164			graphView.showStatus(step, field);
165		}
