167	
168		private void populate() {
169			Random rand = Randomizer.getRandom();
170			field.clear();
171	
172			for (int row = 0; row < field.getDepth(); row++) {
173				for (int col = 0; col < field.getWidth(); col++) {
174					Location location = new Location(row, col);
175	
176	
177					if (rand.nextDouble() <= FLOWER_CREATION_PROBABILITY) {
178						Flower flower = new Flower(field, location);
179						plants.add(flower);
180					} else {
181						Grass grass = new Grass(field, location);
182						plants.add(grass);
183					}
184	
185					populateAnimal(rand, location);
186				}
187			}
188		}
189	
190	
191		private void populateAnimal(Random rand, Location location) {
192			for (AnimalPopulation population : ANIMAL_POPULATIONS) {
193				if (rand.nextDouble() <= population.probability) {
194					Animal animal = population.factory.create(field, location);
195					animals.add(animal);
196					graphView.setColor(population.animalClass, animal.getObjectColor(climate));
197					return;
198				}
199			}
200		}
201	
202	
203		private void updatePlants() {
204			for (Plant plant : plants) {
205				plant.increaseStage(climate);
206			}
207		}
208	
209	
210		private int calculateSickPercentage() {
211			if (animals.isEmpty()) {
212				return 0;
213			}
214	
215			int sickCount = 0;
216			for (Animal animal : animals) {
217				if (animal.isSick()) {
218					sickCount++;
219				}
220			}
221			return (sickCount * 100) / animals.size();
222		}
