  1	import java.util.LinkedHashMap;
  2	import java.util.Map;
  3	
  4	
  5	public class FieldStats {
  6	
  7		private Map<Class<?>, Counter> counters;
  8	
  9		private boolean countsValid;
 10	
 11	
 12		public FieldStats() {
 13	
 14	
 15			counters = new LinkedHashMap<>();
 16			countsValid = true;
 17		}
 18	
 19	
 20		public String getPopulationDetails(Field field) {
 21			StringBuffer buffer = new StringBuffer();
 22			if (!countsValid) {
 23				generateCounts(field);
 24			}
 25			for (Class<?> key : counters.keySet()) {
 26				Counter info = counters.get(key);
 27				buffer.append(info.getName());
 28				buffer.append(": ");
 29				buffer.append(info.getCount());
 30				buffer.append(' ');
 31			}
 32			return buffer.toString();
 33		}
 34	
 35	
 36		public void reset() {
 37			countsValid = false;
 38			for (Class<?> key : counters.keySet()) {
 39				Counter count = counters.get(key);
 40				count.reset();
 41			}
 42		}
 43	
 44	
 45		public void incrementCount(Class<?> animalClass) {
 46			Counter count = counters.get(animalClass);
 47			if (count == null) {
 48	
 49	
 50				count = new Counter(animalClass.getName());
 51				counters.put(animalClass, count);
 52			}
 53			count.increment();
 54		}
 55	
 56	
 57		public void countFinished() {
 58			countsValid = true;
 59		}
 60	
 61	
 62		public boolean isViable(Field field) {
 63	
 64			int nonZero = 0;
 65			if (!countsValid) {
 66				generateCounts(field);
 67			}
 68			for (Class<?> key : counters.keySet()) {
 69				Counter info = counters.get(key);
 70				if (info.getCount() > 0) {
 71					nonZero++;
 72				}
 73			}
 74			return nonZero > 1;
 75		}
 76	
 77	
 78		private void generateCounts(Field field) {
 79			reset();
 80			for (int row = 0; row < field.getDepth(); row++) {
 81				for (int col = 0; col < field.getWidth(); col++) {
 82					Animal animal = field.getAnimalAt(row, col);
 83					if (animal != null) {
 84						incrementCount(animal.getClass());
 85					}
 86				}
 87			}
 88			countsValid = true;
 89		}
 90	
 91	
 92		public int getPopulationCount(Field field, Class<?> key) {
 93			if (!countsValid) {
 94				generateCounts(field);
 95			}
 96			int total = 0;
 97			for (Class<?> currentKey : counters.keySet()) {
 98				if (currentKey.equals(key)) {
 99					Counter counter = counters.get(currentKey);
100					total = total + counter.getCount();
101				}
102			}
103			return total;
104		}
105	}
